        assert_auth_transfer(lending_offer_input_index, lending_offer_output_index, get_lending_offer_asset_id(storage), true);
        assert_auth_transfer(lender_nft_input_index, lender_nft_output_index, get_lender_asset_id(storage), true);
        let amount_to_withdraw: u64 = available_lender_shares(storage);
        assert!(gt_64(amount_to_withdraw, 0));
        assert_closing_withdrawal(vault_output_index, amount_to_withdraw, with_lender_withdrawal(storage, amount_to_withdraw, true));
    }
    fn harvester_withdrawal(storage: VaultStorage, params: HarvesterWithdrawalParams) {
    let (vault_output_index, harvester_auth_input_index, harvester_auth_output_index): HarvesterWithdrawalParams = params;
        assert_auth_transfer(harvester_auth_input_index, harvester_auth_output_index, param::PROTOCOL_HARVESTER_ASSET_ID, false);
        let protocol_fee_to_withdraw: u64 = available_protocol_fee(storage);
        assert!(gt_64(protocol_fee_to_withdraw, 0));
        assert_closing_withdrawal(vault_output_index, protocol_fee_to_withdraw, with_protocol_fee_withdrawal(storage, protocol_fee_to_withdraw));
    }
    fn main() {
    let storage: VaultStorage = (witness::IS_FINALIZED, witness::SUPPLIED_AMOUNT, witness::SUPPLIED_FEE, witness::WITHDRAWN_AMOUNT, witness::WITHDRAWN_PROTOCOL_FEE, witness::LENDER_ASSET_ID, witness::LENDING_OFFER_ASSET_ID);
        assert_storage_with_current(storage);
        match witness::PATH{
    Left(supply_path: SupplyPath) => {
    match supply_path{
    Left(params: SupplyParams) => {
    supply(storage, params, false)}
    ,
    Right(params: SupplyParams) => {
    supply(storage, params, true)}
    ,
    }}
    ,
    Right(withdrawal_path: WithdrawalPath) => {
    match withdrawal_path{
    Left(lender_path: LenderWithdrawalPath) => {
    match lender_path{
    Left(params: PartialWithdrawalParams) => {
    partial_withdrawal(storage, params)}
    ,
    Right(params: FullWithdrawalParams) => {
    full_withdrawal(storage, params)}
    ,
    }}
    ,
    Right(closing_path: ClosingWithdrawalPath) => {
    match closing_path{
    Left(params: LiquidationWithdrawalParams) => {
    liquidation_withdrawal(storage, params)}
    ,
    Right(params: HarvesterWithdrawalParams) => {
    harvester_withdrawal(storage, params)}
    ,
    }}
    ,
    }}
    ,
    }}
}
